		if isUndoubtedlyLucky(i) {
			count++
		}
	}
	fmt.Println(count)
}

func isUndoubtedlyLucky(num int) bool {
	digits := []int{}
	temp := num
	for temp > 0 {
		digits = append(digits, temp%10)
		temp /= 10
	}
	if len(digits) == 0 {
		return false
	}
	unique := make(map[int]bool)
	for _, d := range digits {
		unique[d] = true
	}
	return len(unique) <= 2
}
