package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)

	count := 0
	for i := 1; i <= n; i++ {
		if isUndoubtedlyLucky(i) {
			count++
		}
	}
	fmt.Println(count)
}

func isUndoubtedlyLucky(num int) bool {
	digits := []int{}
	temp := num
	for temp > 0 {
		digits = append(digits, temp%10)
		temp /= 10
	}
	unique := make(map[int]bool)
	for _, d := range digits {
		unique[d] = true
	}
	return len(unique) <= 2
}
