	str := strconv.Itoa(n)
	l := len(str)
	count := 0
	for i := 1; i <= l; i++ {
		for j := 0; j <= 9; j++ {
			for k := j + 1; k <= 9; k++ {
				if j == 0 && k == 0 {
					continue
				}
				count += dfs(str, 0, 0, j, k, true, true)
			}
		}
	}
	fmt.Println(count)
}

func dfs(str string, pos int, num int, x int, y int, tight bool, started bool) int {
	if pos == len(str) {
		if started {
			return 1
		}
		return 0
	}
	limit := 9
	if tight {
		limit = int(str[pos] - '0')
	}
	res := 0
	for d := 0; d <= limit; d++ {
		if d != x && d != y {
			continue
		}
		newTight := tight && (d == limit)
		newStarted := started || d != 0
		res += dfs(str, pos+1, num*10+d, x, y, newTight, newStarted)
	}
	return res
}
