func countUpTo(s string) int {
	n := len(s)
	count := 0
	for x := 0; x <= 9; x++ {
		for y := 0; y <= 9; y++ {
			if x == y {
				continue
			}
			if x == 0 {
				if y == 0 {
					continue
				}
				if y <= int(s[0]-'0') {
					if y < int(s[0]-'0') {
