					}
				}
			} else {
				if x <= int(s[0]-'0') {
					if x < int(s[0]-'0') {
						count += pow(2, n-1)
					} else {
						count += countWithXY(s, x, y)
					}
				}
			}
		}
	}
	return count
}

func countWithXY(s string, x, y int) int {
	n := len(s)
	count := 0
	for i := 0; i < n; i++ {
		d := int(s[i] - '0')
		less := 0
		for _, c := range []int{x, y} {
			if c < d {
				less++
			}
		}
		count += less * pow(2, n-i-1)
		if x != d && y != d {
			break
		}
	}
	return count
}

func pow(a, b int) int {
	res := 1
	for i := 0; i < b; i++ {
		res *= a
	}
	return res
}
