package main

import (
	"fmt"
	"strconv"
)

func main() {
	var n int
	fmt.Scan(&n)
	strN := strconv.Itoa(n)
	length := len(strN)
	count := 0

	// Count all numbers with fewer digits than n
	for i := 1; i < length; i++ {
		count += countForLength(i)
	}

	// Count numbers with the same number of digits as n but <= n
	count += countSameLength(strN)

	fmt.Println(count)
}

func countForLength(l int) int {
	if l == 0 {
		return 0
	}
	total := 0
	for x := 0; x <= 9; x++ {
		for y := x; y <= 9; y++ {
			if x == 0 && y == 0 {
				continue
			}
			if x == 0 {
				// Only y can be used, and first digit must be y
				total += 1
			} else {
				// All combinations of x and y, subtract 1 to exclude all x's (since x is non-zero)
				total += (1 << l) - 1
			}
		}
	}
	return total
}

func countSameLength(s string) int {
	n := len(s)
	count := 0
	for x := 0; x <= 9; x++ {
		for y := x; y <= 9; y++ {
			if x == 0 && y == 0 {
				continue
			}
			if x == 0 {
				// Only y can be used, first digit must be y
				if y > s[0]-'0' {
					continue
				}
				// Generate numbers starting with y followed by any combination of y
				// Check if the number is <= s
				num := ""
				for i := 0; i < n; i++ {
					num += string('0' + y)
				}
				if num <= s {
					count++
				}
			} else {
				// Generate all combinations of x and y with first digit x or y
				// Use backtracking to count valid numbers <= s
				count += backtrack(s, x, y, 0, true, false)
			}
		}
	}
	return count
}

func backtrack(s string, x, y int, pos int, tight bool, started bool) int {
	if pos == len(s) {
		return 1
	}
	maxDigit := 9
	if tight {
		maxDigit = s[pos] - '0'
	}
	total := 0
	for d := 0; d <= maxDigit; d++ {
		if d != x && d != y {
			continue
		}
		newTight := tight && (d == maxDigit)
		newStarted := started || (d != 0)
		if !newStarted && d == 0 {
			continue
		}
		total += backtrack(s, x, y, pos+1, newTight, newStarted)
	}
	return total
}
