package main

import (
	"fmt"
)

func main() {
	var n int
	fmt.Scan(&n)

	count := 0

	// Iterate over all possible pairs of digits (x, y)
	for x := 0; x <= 9; x++ {
		for y := x; y <= 9; y++ {
			// Generate all numbers using digits x and y that are <= n
			// We need to consider numbers with up to the same number of digits as n
			// Use BFS approach
			// Start with single digit numbers (non-zero)
			if x == 0 && y == 0 {
				continue // Can't form any positive number
			}

			// Generate all possible numbers with digits x and y
			// We'll use a recursive approach to generate all combinations
			// But to avoid duplicates, we generate each number once
			// For efficiency, we generate numbers digit by digit
			// and check if they are <= n

			// Use a set to avoid counting duplicates
			seen := make(map[int]bool)

			// Generate numbers with digits x and y
			// Start with first digit (can't be 0)
			firstDigits := []int{}
			if x != 0 {
				firstDigits = append(firstDigits, x)
			}
			if y != 0 {
				firstDigits = append(firstDigits, y)
			}

			// Remove duplicates in firstDigits
			firstSet := make(map[int]bool)
			for _, d := range firstDigits {
				firstSet[d] = true
			}
			firstDigits = []int{}
			for d := range firstSet {
				firstDigits = append(firstDigits, d)
			}

			// BFS
			queue := []int{}
			for _, d := range firstDigits {
				if d <= n {
					queue = append(queue, d)
				}
			}

			for len(queue) > 0 {
				num := queue[0]
				queue = queue[1:]

				if seen[num] {
					continue
				}
				seen[num] = true

				// Add this number to count
				count++

				// Generate next numbers by appending x or y
				for _, d := range []int{x, y} {
					newNum := num*10 + d
					if newNum <= n && !seen[newNum] {
						queue = append(queue, newNum)
					}
				}
			}
		}
	}

	fmt.Println(count)
}
